const guides = [];
for (const [key, data] of Object.entries(summaryData)) {
  const writing = currentWriting.find((item) => item.id === `summary-${key}`);
  const source = currentTexts.find((item) => item.id === writing?.sourceTextId);
  if (!writing || !source) throw new Error(`Нет связанного изложения ${key}`);
  guides.push({
    id: `guide-${writing.id}`, revision: 1, writingId: writing.id, writingRevision: writing.revision,
    sourceTextId: source.id, sourceTextRevision: source.revision, title: `Учебный разбор: ${source.title}`, provenance,
    routes: [{
      promptId: "1", purpose: "Сохранить все микротемы и существенные ограничения, применив сжатие во всём тексте.",
      plan: data.plan, stages: data.stages,
      strong: { text: data.strong, analysis: ["Это один из возможных оригинальных ответов, а не текст для механического заучивания.", ...data.notes] },
      weak: { text: data.weak, analysis: data.weakAnalysis },
      criteriaNotes: data.notes.map((note) => ({ code: note.slice(0, 3), text: note.slice(5) })),
      checkpoints: ["Сравните каждый абзац со своей микротемой: какая мысль и какое условие сохранены?", "Назовите конкретный приём в каждой промежуточной версии.", "Исправьте слабый ответ без добавления собственных мыслей.", "Отдельно проверьте орфографию, пунктуацию, грамматику, речь и факты; содержание не подтверждается одним счётчиком слов."],
    }],
  });
}
for (const [key, routes] of Object.entries(essayData)) {
  const writing = currentWriting.find((item) => item.id === `essay-${key}`);
  const source = currentTexts.find((item) => item.id === writing?.sourceTextId);
  if (!writing || !source) throw new Error(`Нет связанного сочинения ${key}`);
  guides.push({ id: `guide-${writing.id}`, revision: key === "audit-yard" ? 2 : 1, writingId: writing.id, writingRevision: writing.revision, sourceTextId: source.id, sourceTextRevision: source.revision, title: `Учебный разбор: ${source.title}`, provenance, routes });
}
await fs.writeFile("apps/showcase/src/oge/writing-guides.json", `${JSON.stringify({ schemaVersion: 1, guides }, null, 2)}\n`);
console.log(`Подготовлены разборы письменных работ: ${guides.length}, маршруты: ${guides.reduce((sum, item) => sum + item.routes.length, 0)}.`);
